// Claude's review tests for A40 (a mock that can never answer). agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { patternCovers, unreachableMocks } from './reachability';
import type { Mock } from './types';

function mock(id: string, method: Mock['method'], urlPattern: string, extra: Partial<Mock> = {}): Mock {
  return {
    id, name: id, enabled: true, method, urlPattern, source: 'manual', createdAt: 0,
    response: { status: 200, headers: {}, body: '', bodyEncoding: 'text', delayMs: 0 }, ...extra,
  };
}

describe('patternCovers', () => {
  it('equal patterns cover each other', () => {
    expect(patternCovers('/api/users', '/api/users')).toBe(true);
  });
  it('a :param covers any one segment, a literal does not cover a param', () => {
    expect(patternCovers('/api/users/:id', '/api/users/7')).toBe(true);
    expect(patternCovers('/api/users/:id', '/api/users/:userId')).toBe(true);
    expect(patternCovers('/api/users/7', '/api/users/:id')).toBe(false);
    expect(patternCovers('/api/users/:id', '/api/users/7/orders')).toBe(false);
  });
  it('a trailing *rest covers one or more segments', () => {
    expect(patternCovers('/api/*rest', '/api/users/7')).toBe(true);
    expect(patternCovers('/api/*rest', '/api/x')).toBe(true);
    expect(patternCovers('/api/*rest', '/api')).toBe(false);
    expect(patternCovers('/api/*rest', '/other/x')).toBe(false);
  });
  it('a host must match: a path-only pattern covers only path-only ones', () => {
    expect(patternCovers('https://a.test/api/:id', 'https://a.test/api/1')).toBe(true);
    expect(patternCovers('https://a.test/api/:id', 'https://b.test/api/1')).toBe(false);
    expect(patternCovers('/api/:id', 'https://a.test/api/1')).toBe(false);
  });
  it('when unsure (optional parts), no', () => {
    expect(patternCovers('/api{/:id}', '/api/1')).toBe(false);
    expect(patternCovers('/v1\\:batch', '/v1\\:batch')).toBe(true);
  });
  it('a host-bound pattern keeps its escapes (PR #1): \\: is a literal colon, not a parameter', () => {
    expect(patternCovers(String.raw`https://a.test/v1/items\:batch`, 'https://a.test/v1/items/7')).toBe(false);
    expect(patternCovers(String.raw`https://a.test/v1/items\:batch`, String.raw`https://a.test/v1/items\:batch`)).toBe(true);
    expect(patternCovers('https://A.TEST:443/x/:id', 'https://a.test/x/1')).toBe(true);
  });
});

describe('unreachableMocks', () => {
  it('a mock below a wider, plain, enabled one never answers', () => {
    const r = unreachableMocks([mock('all', 'ANY', '/api/users/:id'), mock('seven', 'GET', '/api/users/7')]);
    expect([...r.keys()]).toEqual(['seven']);
    expect(r.get('seven')).toEqual({ byId: 'all', reason: 'Never answers: all above catches all its calls' });
  });
  it('order matters: the wider one below is fine', () => {
    expect(unreachableMocks([mock('seven', 'GET', '/api/users/7'), mock('all', 'ANY', '/api/users/:id')]).size).toBe(0);
  });
  it('a different method is not caught', () => {
    expect(unreachableMocks([mock('get', 'GET', '/api/x'), mock('post', 'POST', '/api/x')]).size).toBe(0);
    expect(unreachableMocks([mock('get', 'GET', '/api/x'), mock('any', 'ANY', '/api/x')]).size).toBe(0);
  });
  it('conditions: a later mock with conditions is tried first; an earlier one with conditions does not catch all', () => {
    expect(unreachableMocks([mock('all', 'GET', '/api/x'), mock('cond', 'GET', '/api/x', { match: { query: { a: '1' } } })]).size).toBe(0);
    expect(unreachableMocks([mock('cond', 'GET', '/api/x', { match: { query: { a: '1' } } }), mock('all', 'GET', '/api/x')]).size).toBe(0);
  });
  it('a disabled mock above catches nothing; a disabled mock below is not warned about', () => {
    expect(unreachableMocks([mock('off', 'GET', '/api/x', { enabled: false }), mock('b', 'GET', '/api/x')]).size).toBe(0);
    expect(unreachableMocks([mock('a', 'GET', '/api/x'), mock('off', 'GET', '/api/x', { enabled: false })]).size).toBe(0);
  });
  it('a GraphQL operation above does not catch other operations', () => {
    expect(unreachableMocks([mock('op', 'POST', '/graphql', { graphqlOperation: 'GetUser' }), mock('other', 'POST', '/graphql', { graphqlOperation: 'GetCart' })]).size).toBe(0);
    expect(unreachableMocks([mock('any', 'POST', '/graphql'), mock('op', 'POST', '/graphql', { graphqlOperation: 'GetCart' })]).size).toBe(1);
  });
  it('the first catcher is named', () => {
    const r = unreachableMocks([mock('a', 'ANY', '/api/*rest'), mock('b', 'GET', '/api/:x'), mock('c', 'GET', '/api/1')]);
    expect(r.get('b')?.byId).toBe('a');
    expect(r.get('c')?.byId).toBe('a');
  });
});
